"""
    Computes free space on the figure on both sides.
    :param width:
    :param n: number of algorithms
    :return:
    """
def center(width: Any, n: Any) -> object {
    max_unit = 1;
    free_space = width - (n * max_unit);
    free_space = max(0, (free_space / max_unit));
    free_left = free_space / 2;
    free_right = free_space / 2;
    return (free_left, free_right);
}

"""Computes precision at standard cutoff ranks: [5, 10, 15, 20, 30, 100, 200, 500, 1000]

    Args:
        result2rank: A dict of source to ranks of good translation candidates.
        total_terms: The expected term count.

    Returns:
        A dict containing a precision value for each cutoff rank

    """
def precision_ranges(result2rank: Any, total_terms: Any) -> object {
    map_of_prec = `dict();
    for cutoff in [5, 10, 15, 20, 30, 100, 200, 500, 1000] {
        map_of_prec[cutoff] = (
            sum(
                1.0
                for ranks in result2rank.values()
                if (
                    len(
                        [
                            r
                            for r in ranks
                            if (r <= cutoff)
                        ]
                    )
                    > 0
                )
            )
            / total_terms
        );
    }
    return map_of_prec;
}

